1594	\begin{definition}[Canonical parameters of the Pauli basis test]\label{def:introparams}
1595		\lean{MIPStarRE.QPBT.introParamsC, MIPStarRE.QPBT.introParamsTuple, MIPStarRE.QPBT.AdmissibleParams.ofTuple, MIPStarRE.QPBT.introParams}
